import React, { Suspense, lazy } from "react";
import Navigation from "../../navigationpage";
import BlurHome from "./blurHome";
const LazyHome = lazy(() => import("../home"));
const LazyRoomCarts = lazy(() => import("../roomcarts"));
const LazyFoodCards = lazy(() => import("../foodcards"));
import Skeleton from 'react-loading-skeleton'
import 'react-loading-skeleton/dist/skeleton.css'



const MainHome = () => {
  return (
    <div>
      <Navigation />
      <Suspense fallback={<BlurHome/>}>
        <LazyHome />
      </Suspense>
      <Suspense fallback={<div>Loading RoomCarts...</div>}>
        <LazyRoomCarts />
      </Suspense>
      <Suspense fallback={<div>Loading FoodCards...</div>}>
        <LazyFoodCards />
      </Suspense>
    </div>
  );
};

export default MainHome;
